def describe(graph: Graph, node, absolute) -> str:
    kind = node.get("type")
    name = node.get("name") or ""
    x, y, w, h = bounds(absolute, node.get("size"))
    bits = [f'{kind} "{name[:60]}" [{guid_key(node.get("guid"))}] {w:.0f}x{h:.0f} @{x:.0f},{y:.0f}']
    if node.get("visible") is False:
        bits.append("HIDDEN")
    if node.get("opacity") is not None and node.get("opacity") < 1:
        bits.append(f"opacity={node['opacity']:.2f}")
    if node.get("isStateGroup"):
        bits.append("COMPONENT_SET")
    if node.get("mask"):
        bits.append("MASK")
    if kind == "INSTANCE":
        master = graph.by_id.get(guid_key((node.get("symbolData") or {}).get("symbolID")))
        if master is not None:
            bits.append(f'of "{master.get("name")}"')
    paints = [paint_summary(p) for p in node.get("fillPaints") or [] if p.get("visible") is not False]
    if paints:
        rendered = []
        for p in paints[:3]:
            if p["type"] == "SOLID":
                rendered.append(p["hex"] + (f"@{p['alpha']}" if p["alpha"] < 1 else ""))
            elif p["type"] == "IMAGE":
                rendered.append(f"image:{(p.get('image') or '')[:10]}")
            else:
                rendered.append(p["type"].lower())
        bits.append("fill=" + ",".join(rendered))
    if kind == "TEXT":
        text = ((node.get("textData") or {}).get("characters") or "").replace("\n", " / ")
        font = node.get("fontName") or {}
        bits.append(f'{font.get("family")} {font.get("style")} {node.get("fontSize")}px: "{text[:80]}"')
    if node.get("autoRename") is False and kind == "TEXT":
        bits.append("(named)")
    return "  ".join(bits)


def render_outline(graph: Graph, depth=3, page_name=None, node_id=None, max_lines=3000) -> str:
    lines: list = []
    if node_id:
        node = graph.by_id.get(node_id)
        if node is None:
            raise FigError(f"no node {node_id}")
        emit(graph, node, graph.absolute_matrix(node), 0, depth, lines, max_lines)
    for page in [] if node_id else graph.pages:
        if page_name and page.get("name") != page_name:
            continue
        flags = []
        if page.get("visible") is False:
            flags.append("HIDDEN")
        if page.get("internalOnly"):
            flags.append("INTERNAL-ONLY (library masters)")
        lines.append(f'PAGE "{page.get("name")}" [{guid_key(page.get("guid"))}] {" ".join(flags)}'.rstrip())
        for child in graph.kids(page):
            if child.get("styleType") not in (None, "NONE") or child.get("type") in ("VARIABLE", "VARIABLE_SET"):
                continue
            emit(graph, child, matrix_of(child), 1, depth, lines, max_lines)
    truncated = len(lines) > max_lines
    return "\n".join(lines[:max_lines]) + (
        "\n… (truncated; narrow with --page/--node/--depth)\n" if truncated else "\n"
    )


def emit(graph, node, absolute, level, depth, lines, max_lines):
    if len(lines) > max_lines:
        return
    lines.append("  " * level + describe(graph, node, absolute))
    kids = graph.kids(node)
    if level >= depth:
        if kids:
            lines.append("  " * (level + 1) + f"… {len(kids)} children")
        return
    for child in kids:
        emit(graph, child, multiply(absolute, matrix_of(child)), level + 1, depth, lines, max_lines)

"""Draw a decoded Figma node as SVG from the geometry, glyph outlines and layout Figma saved in the file."""

from __future__ import annotations

import base64
import math
import os
import struct
from collections import Counter, defaultdict

from fig_decode import (
    IDENTITY,
    Graph,
    apply,
    guid_key,
    hash_hex,
    hex_color,
    matrix_of,
    multiply,
