# svg: draw a node from Figma's own baked geometry
# ---------------------------------------------------------------------------

# commandsBlob opcodes, each followed by float32-LE params with no padding.
# 0x03 is a QUADRATIC curve in real files (TrueType glyph outlines use it); some
# hand-built encoders wrote it as a parameterless ClosePath, so that reading is the fallback.
PATH_PARAMS = {0: 0, 1: 2, 2: 2, 3: 4, 4: 6}  # 0 subpath break, 1 M, 2 L, 3 Q, 4 C
PATH_PARAMS_CLOSE = {**PATH_PARAMS, 3: 0}
FRAME_LIKE = {"FRAME", "SYMBOL", "INSTANCE", "SECTION", "SLIDE", "SLIDE_ROW", "SLIDE_GRID"}
RECT_LIKE = FRAME_LIKE | {"RECTANGLE", "ROUNDED_RECTANGLE"}
BLEND_CSS = {
    "MULTIPLY": "multiply",
    "SCREEN": "screen",
    "OVERLAY": "overlay",
    "DARKEN": "darken",
    "LIGHTEN": "lighten",
    "COLOR_DODGE": "color-dodge",
    "COLOR_BURN": "color-burn",
    "HARD_LIGHT": "hard-light",
    "SOFT_LIGHT": "soft-light",
    "DIFFERENCE": "difference",
    "EXCLUSION": "exclusion",
    "HUE": "hue",
    "SATURATION": "saturation",
    "COLOR": "color",
    "LUMINOSITY": "luminosity",
}


def num(value: float) -> str:
    text = f"{value:.2f}".rstrip("0").rstrip(".")
    return "0" if text in ("-0", "") else text


def blob_path(blob: bytes, m) -> str | None:
    return read_path(blob, m, PATH_PARAMS) or read_path(blob, m, PATH_PARAMS_CLOSE)


def read_path(blob: bytes, m, table) -> str | None:
    parts, off, size = [], 0, len(blob)
    while off < size:
        op = blob[off]
        off += 1
        count = table.get(op)
        if count is None or off + 4 * count > size:
            return None
        values = struct.unpack_from(f"<{count}f", blob, off) if count else ()
        off += 4 * count
        if op == 0:
            continue
        if op == 3 and not count:
            parts.append("Z")
            continue
        coords = []
        for i in range(0, count, 2):
            x, y = apply(m, values[i], values[i + 1])
            coords += [num(x), num(y)]
        parts.append({1: "M", 2: "L", 3: "Q", 4: "C"}[op] + " " + " ".join(coords))
    return " ".join(parts) or None


def decode_network(blob: bytes):
    """vectorNetworkBlob -> (vertices, segments, regions). Little-endian, no padding."""
    if len(blob) < 12:
        return None
    nv, ns, nr = struct.unpack_from("<3I", blob, 0)
    off = 12
    if 12 + nv * 12 + ns * 28 > len(blob):
        return None
    vertices = []
    for _ in range(nv):
        _, x, y = struct.unpack_from("<I2f", blob, off)
        vertices.append((x, y))
        off += 12
    segments = []
    for _ in range(ns):
        _, a, adx, ady, b, bdx, bdy = struct.unpack_from("<2I2fI2f", blob, off)
        segments.append((a, (adx, ady), b, (bdx, bdy)))
        off += 28
    regions = []
    for _ in range(nr):
        flags, loop_count = struct.unpack_from("<2I", blob, off)
        off += 8
        loops = []
        for _ in range(loop_count):
            (count,) = struct.unpack_from("<I", blob, off)
            off += 4
            loops.append(list(struct.unpack_from(f"<{count}I", blob, off)))
            off += 4 * count
        regions.append(("nonzero" if flags & 1 else "evenodd", loops))
    return vertices, segments, regions


def network_paths(node, m, blobs):
    """Region loops become filled subpaths; segments no region uses become open strokes."""
    blob_index = (node.get("vectorData") or {}).get("vectorNetworkBlob")
    graph_blobs = blobs
    if blob_index is None or blob_index >= len(graph_blobs):
        return [], []
    network = decode_network(graph_blobs[blob_index].get("bytes") or b"")
    if network is None:
        return [], []
    vertices, segments, regions = network
    size = node.get("size") or {}
    norm = (node.get("vectorData") or {}).get("normalizedSize") or size
    sx = (size.get("x") or 0) / norm["x"] if norm.get("x") else 1
    sy = (size.get("y") or 0) / norm["y"] if norm.get("y") else 1
    point = lambda x, y: apply(m, x * sx, y * sy)  # noqa: E731

    def curve(seg, reverse):
        a, ta, b, tb = seg
        if reverse:
            a, ta, b, tb = b, tb, a, ta
        (x0, y0), (x1, y1) = vertices[a], vertices[b]
        end = point(x1, y1)
        if ta == (0, 0) and tb == (0, 0):
            return a, b, f"L {num(end[0])} {num(end[1])}"
        c1, c2 = point(x0 + ta[0], y0 + ta[1]), point(x1 + tb[0], y1 + tb[1])
        return a, b, "C " + " ".join(num(v) for v in (*c1, *c2, *end))

    used = set()
    fills = []
    for rule, loops in regions:
        subpaths = []
        for loop in loops:
            if not loop:
                continue
            for first_reversed in (False, True):
                cursor, pieces, ok = None, [], True
                for i, index in enumerate(loop):
                    seg = segments[index]
                    reverse = first_reversed if i == 0 else (seg[2] == cursor and seg[0] != cursor)
                    if i and cursor not in (seg[0], seg[2]):
                        ok = False
                        break
                    start, cursor, text = curve(seg, reverse)
                    if i == 0:
                        x, y = point(*vertices[start])
                        pieces.append(f"M {num(x)} {num(y)}")
                    pieces.append(text)
                if ok:
                    subpaths.append(" ".join(pieces) + " Z")
                    used.update(loop)
                    break
        if subpaths:
            fills.append((" ".join(subpaths), rule))
    strokes = []
    for index, seg in enumerate(segments):
        if index in used:
            continue
        x, y = point(*vertices[seg[0]])
        strokes.append(f"M {num(x)} {num(y)} {curve(seg, False)[2]}")
    if not regions and strokes:
        # A network with no regions fills every closed loop it draws (Figma fills
        # region-less closed shapes); without loop detection, fill the open runs too.
        fills.append((" ".join(strokes), "nonzero"))
    return fills, strokes


def corner_radii(node):
    if node.get("rectangleCornerRadiiIndependent"):
        return [
            node.get(k) or 0
            for k in (
                "rectangleTopLeftCornerRadius",
                "rectangleTopRightCornerRadius",
                "rectangleBottomRightCornerRadius",
                "rectangleBottomLeftCornerRadius",
            )
        ]
    return [node.get("cornerRadius") or 0] * 4


def rect_path(node, m) -> str:
    w, h = (node.get("size") or {}).get("x", 0), (node.get("size") or {}).get("y", 0)
    tl, tr, br, bl = (min(r, w / 2, h / 2) for r in corner_radii(node))
    k = 0.5523
    pts = []

    def p(x, y):
        return " ".join(num(v) for v in apply(m, x, y))

    pts.append(f"M {p(tl, 0)} L {p(w - tr, 0)}")
    if tr:
        pts.append(f"C {p(w - tr + tr * k, 0)} {p(w, tr - tr * k)} {p(w, tr)}")
    pts.append(f"L {p(w, h - br)}")
    if br:
        pts.append(f"C {p(w, h - br + br * k)} {p(w - br + br * k, h)} {p(w - br, h)}")
    pts.append(f"L {p(bl, h)}")
    if bl:
        pts.append(f"C {p(bl - bl * k, h)} {p(0, h - bl + bl * k)} {p(0, h - bl)}")
    pts.append(f"L {p(0, tl)}")
    if tl:
        pts.append(f"C {p(0, tl - tl * k)} {p(tl - tl * k, 0)} {p(tl, 0)}")
    return " ".join(pts) + " Z"


def ellipse_path(node, m) -> str:
    w, h = (node.get("size") or {}).get("x", 0), (node.get("size") or {}).get("y", 0)
    rx, ry, k = w / 2, h / 2, 0.5523
    p = lambda x, y: " ".join(num(v) for v in apply(m, x, y))  # noqa: E731
    return (
        f"M {p(w, ry)} C {p(w, ry + ry * k)} {p(rx + rx * k, h)} {p(rx, h)} "
        f"C {p(rx - rx * k, h)} {p(0, ry + ry * k)} {p(0, ry)} "
        f"C {p(0, ry - ry * k)} {p(rx - rx * k, 0)} {p(rx, 0)} "
        f"C {p(rx + rx * k, 0)} {p(w, ry - ry * k)} {p(w, ry)} Z"
    )


def invert(m):
    det = m[0] * m[4] - m[1] * m[3]
    if abs(det) < 1e-12:
        return None
    a, b, c, d = m[4] / det, -m[1] / det, -m[3] / det, m[0] / det
    return (a, b, -(a * m[2] + b * m[5]), c, d, -(c * m[2] + d * m[5]))


def svg_matrix(m) -> str:
    return "matrix(" + " ".join(num_precise(v) for v in (m[0], m[3], m[1], m[4], m[2], m[5])) + ")"


def num_precise(value: float) -> str:
    return f"{value:.6g}"


def image_size(path: str):
    with open(path, "rb") as handle:
        head = handle.read(64 * 1024)
    if head[:4] == b"\x89PNG":
        return struct.unpack(">II", head[16:24])
    if head[:4] == b"GIF8":
        return struct.unpack("<HH", head[6:10])
    if head[:3] == b"\xff\xd8\xff":
        off = 2
        while off + 9 < len(head):
            if head[off] != 0xFF:
                off += 1
                continue
            marker = head[off + 1]
            length = struct.unpack(">H", head[off + 2 : off + 4])[0]
            if marker in (0xC0, 0xC1, 0xC2):
                h, w = struct.unpack(">HH", head[off + 5 : off + 9])
                return w, h
            off += 2 + length
    return None


class SvgWriter:
    def __init__(self, graph: Graph, directory: str, include_hidden: bool, embed: bool):
        self.graph = graph
        self.directory = directory
        self.include_hidden = include_hidden
        self.embed = embed
        self.defs: list[str] = []
        self.ids = 0
        self.skipped: Counter = Counter()

    def uid(self, prefix: str) -> str:
        self.ids += 1
        return f"{prefix}{self.ids}"

    # --- paints -------------------------------------------------------------

    def paint_fill(self, paint, node, m, clip_d=None) -> str | None:
        """An SVG fill value for one paint, or None to draw it another way."""
        kind = paint.get("type")
        opacity = paint.get("opacity", 1)
        if kind == "SOLID":
            color = paint.get("color") or {}
            alpha = color.get("a", 1) * opacity
            return f'fill="{hex_color(color)}"' + (f' fill-opacity="{num_precise(alpha)}"' if alpha < 1 else "")
        if kind in ("GRADIENT_LINEAR", "GRADIENT_RADIAL", "GRADIENT_ANGULAR", "GRADIENT_DIAMOND"):
            stops = paint.get("stops") or paint.get("stopsVar") or []
            if not stops:
                return None
            transform = paint.get("transform") or {}
            inverse = invert(matrix_of({"transform": transform})) or IDENTITY
            size = node.get("size") or {}
            unit_to_user = multiply(m, (size.get("x", 0), 0, 0, 0, size.get("y", 0), 0))
            gradient_to_user = multiply(unit_to_user, inverse)
            gid = self.uid("g")
            stop_xml = "".join(
                f'<stop offset="{num_precise(s.get("position", 0))}" stop-color="{hex_color(s.get("color"))}" '
                f'stop-opacity="{num_precise((s.get("color") or {}).get("a", 1) * opacity)}"/>'
                for s in stops
            )
            if kind == "GRADIENT_LINEAR":
                self.defs.append(
                    f'<linearGradient id="{gid}" gradientUnits="userSpaceOnUse" x1="0" y1="0.5" x2="1" y2="0.5" '
                    f'gradientTransform="{svg_matrix(gradient_to_user)}">{stop_xml}</linearGradient>'
                )
            else:
                if kind != "GRADIENT_RADIAL":
                    self.skipped[f"{kind.lower()} drawn as radial"] += 1
                self.defs.append(
                    f'<radialGradient id="{gid}" gradientUnits="userSpaceOnUse" cx="0.5" cy="0.5" r="0.5" '
                    f'gradientTransform="{svg_matrix(gradient_to_user)}">{stop_xml}</radialGradient>'
                )
            return f'fill="url(#{gid})"'
        self.skipped[f"{(kind or 'unknown').lower()} paint"] += 1
        return None

    def image_element(self, paint, node, m, shape_d, rule) -> str | None:
        digest = hash_hex((paint.get("image") or {}).get("hash"))
        if not digest:
            return None
        images_dir = os.path.join(self.directory, "images")
        files = [f for f in os.listdir(images_dir)] if os.path.isdir(images_dir) else []
        match = next((f for f in files if f.startswith(digest + ".")), None)
        if match is None:
            self.skipped["image not in images/ (decode with --images all; a copied selection has no pixels)"] += 1
            return None
        path = os.path.join(images_dir, match)
        natural = image_size(path) or (paint.get("originalImageWidth"), paint.get("originalImageHeight"))
        if not natural or not natural[0]:
            self.skipped["image of unknown size"] += 1
            return None
        iw, ih = natural
        size = node.get("size") or {}
        w, h = size.get("x", 0), size.get("y", 0)
        mode = paint.get("imageScaleMode") or "FILL"
        if mode == "STRETCH" and paint.get("transform"):
            # STRETCH is Figma's crop: the transform maps the node's unit square into the image's.
            inverse = invert(matrix_of({"transform": paint["transform"]})) or IDENTITY
            placed = multiply(multiply(m, (w, 0, 0, 0, h, 0)), multiply(inverse, (1 / iw, 0, 0, 0, 1 / ih, 0)))
        elif mode == "TILE":
            scale = paint.get("scale") or 1
            self.skipped["tiled image drawn once"] += 1
            placed = multiply(m, (scale, 0, 0, 0, scale, 0))
        else:
            scale = max(w / iw, h / ih) if mode in ("FILL", "STRETCH") else min(w / iw, h / ih)
            placed = multiply(m, (scale, 0, (w - iw * scale) / 2, 0, scale, (h - ih * scale) / 2))
        if paint.get("rotation"):
            self.skipped["rotated image fill"] += 1
        if self.embed:
            with open(path, "rb") as handle:
                data = handle.read()
            # Sniffed, not taken from the name: images fetched over REST can be saved under any extension.
            kind = sniff_image(data[:64])
            mime = {"jpg": "jpeg", "svg": "svg+xml"}.get(kind, kind)
            href = f"data:image/{mime};base64," + base64.b64encode(data).decode("ascii")
        else:
            href = os.path.abspath(path)
        cid = self.uid("c")
        self.defs.append(f'<clipPath id="{cid}"><path d="{shape_d}" clip-rule="{rule}"/></clipPath>')
        opacity = paint.get("opacity", 1)
        return (
            f'<g clip-path="url(#{cid})"{f" opacity={chr(34)}{num_precise(opacity)}{chr(34)}" if opacity < 1 else ""}>'
            f'<image href="{href}" width="{iw}" height="{ih}" preserveAspectRatio="none" '
            f'transform="{svg_matrix(placed)}"/></g>'
        )

    def draw(self, paths, paints, node, m, out):
        """Each visible paint, bottom to top, over the same shapes."""
        for paint in paints or []:
            if paint.get("visible") is False:
                continue
            for d, rule in paths:
                if paint.get("type") == "IMAGE":
                    element = self.image_element(paint, node, m, d, rule)
                    if element:
                        out.append(element)
                    continue
                fill = self.paint_fill(paint, node, m)
                if fill:
                    blend = BLEND_CSS.get(paint.get("blendMode"))
                    style = f' style="mix-blend-mode:{blend}"' if blend else ""
                    out.append(f'<path d="{d}" {fill} fill-rule="{rule}"{style}/>')

    # --- geometry -----------------------------------------------------------

    def geometry(self, key, node, m):
        result = []
        for path in node.get(key) or []:
            index = path.get("commandsBlob")
            if index is None or index >= len(self.graph.blobs):
                continue
            d = blob_path(self.graph.blobs[index].get("bytes") or b"", m)
            if d:
                result.append((d, "evenodd" if path.get("windingRule") == "ODD" else "nonzero"))
        return result

    def text_runs(self, node, m):
        """Glyph outlines Figma already laid out, grouped by the paint each run uses."""
        derived = node.get("derivedTextData") or {}
        glyphs = derived.get("glyphs") or []
        if not glyphs:
            self.skipped["text without baked glyphs"] += 1
            return []
        text = node.get("textData") or {}
        style_ids = text.get("characterStyleIDs") or []
        overrides = {o.get("styleID"): o for o in text.get("styleOverrideTable") or []}
        groups: dict = defaultdict(list)
        for glyph in glyphs:
            index = glyph.get("commandsBlob")
            if index is None or index >= len(self.graph.blobs):
                continue
            pos = glyph.get("position") or {}
            size = glyph.get("fontSize") or node.get("fontSize") or 0
            glyph_m = multiply(m, (size, 0, pos.get("x", 0), 0, -size, pos.get("y", 0)))
            d = blob_path(self.graph.blobs[index].get("bytes") or b"", glyph_m)
            if not d:
                continue
            first = glyph.get("firstCharacter", 0)
            style = style_ids[first] if first < len(style_ids) else 0
            groups[style].append(d)
        runs = []
        for style, ds in groups.items():
            paints = (overrides.get(style) or {}).get("fillPaints") or node.get("fillPaints")
            runs.append(([(" ".join(ds), "nonzero")], paints))
        return runs

    def fill_shapes(self, node, m):
        baked = self.geometry("fillGeometry", node, m)
        if baked:
            return baked, []
        kind = node.get("type")
        if (node.get("vectorData") or {}).get("vectorNetworkBlob") is not None:
            return network_paths(node, m, self.graph.blobs)
        if kind in RECT_LIKE:
            return [(rect_path(node, m), "nonzero")], []
        if kind == "ELLIPSE":
            return [(ellipse_path(node, m), "nonzero")], []
        return [], []

    # --- nodes --------------------------------------------------------------

    def render(self, node, m, ctx, out, path=()):
        if node.get("visible") is False and not self.include_hidden:
            return
        node = self.apply_context(node, ctx, path)
        if node.get("visible") is False and not self.include_hidden:
            return
        m = multiply(m, matrix_of(node)) if path or ctx.get("child") else m
        body: list[str] = []
        kind = node.get("type")

        if kind == "TEXT":
            for paths, paints in self.text_runs(node, m):
                self.draw(paths, paints, node, m, body)
        else:
            fills, open_strokes = self.fill_shapes(node, m)
            self.draw(fills, node.get("fillPaints"), node, m, body)
        strokes = self.geometry("strokeGeometry", node, m)
        if strokes:
            # Figma pre-flattens strokes into outlines: fill them with the stroke paint.
            self.draw(strokes, node.get("strokePaints"), node, m, body)
        elif kind != "TEXT" and node.get("strokePaints") and node.get("strokeWeight", 1) > 0:
            fills, open_strokes = self.fill_shapes(node, m)
            outline = [d for d, _ in fills] + open_strokes
            scale = math.sqrt(abs(m[0] * m[4] - m[1] * m[3])) or 1
            for paint in node.get("strokePaints") or []:
                fill = self.paint_fill(paint, node, m) if paint.get("visible") is not False else None
                if fill and outline:
                    stroke = fill.replace("fill=", "stroke=").replace("fill-opacity=", "stroke-opacity=")
                    body.append(
                        f'<path d="{" ".join(outline)}" fill="none" {stroke} '
                        f'stroke-width="{num(node.get("strokeWeight", 1) * scale)}"/>'
                    )
            self.skipped["stroke drawn centered (no baked stroke outline)"] += 1

        children = self.children_of(node, ctx, path)
        if kind == "BOOLEAN_OPERATION" and node.get("fillGeometry"):
            children = []  # the operands are inputs; the node's own geometry is the result
        child_out: list[str] = []
        clip_rest = None
        for child_node, child_ctx, child_path in children:
            if child_node.get("mask") and child_node.get("visible") is not False:
                child_node = self.apply_context(child_node, child_ctx, child_path)
                mask_m = multiply(m, matrix_of(child_node))
                shapes, _ = self.fill_shapes(child_node, mask_m)
                if shapes:
                    cid = self.uid("m")
                    self.defs.append(
                        f'<clipPath id="{cid}">'
                        + "".join(f'<path d="{d}" clip-rule="{r}"/>' for d, r in shapes)
                        + "</clipPath>"
                    )
                    child_out.append(f'<g clip-path="url(#{cid})">')
                    clip_rest = cid
                    if child_node.get("maskType") not in (None, "ALPHA", "OUTLINE", "VECTOR"):
                        self.skipped[f"{child_node.get('maskType')} mask drawn as a clip"] += 1
                continue
            self.render(child_node, m, child_ctx, child_out, child_path)
        if clip_rest:
            child_out.append("</g>")
        if child_out:
            clips = kind in FRAME_LIKE and not node.get("frameMaskDisabled") and not node.get("resizeToFit")
            if clips:
                cid = self.uid("f")
                self.defs.append(f'<clipPath id="{cid}"><path d="{rect_path(node, m)}"/></clipPath>')
                body.append(f'<g clip-path="url(#{cid})">{"".join(child_out)}</g>')
            else:
                body.extend(child_out)

        if not body:
            return
        attributes = []
        if node.get("opacity") is not None and node["opacity"] < 1:
            attributes.append(f'opacity="{num_precise(node["opacity"])}"')
        blend = BLEND_CSS.get(node.get("blendMode"))
        if blend:
            attributes.append(f'style="mix-blend-mode:{blend}"')
        effect_filter = self.effects(node, m)
        if effect_filter:
            attributes.append(f'filter="url(#{effect_filter})"')
        if attributes:
            out.append(f"<g {' '.join(attributes)}>" + "".join(body) + "</g>")
        else:
            out.extend(body)

    def effects(self, node, m) -> str | None:
        scale = math.sqrt(abs(m[0] * m[4] - m[1] * m[3])) or 1
        layers = []
        for effect in node.get("effects") or []:
            if effect.get("visible") is False:
                continue
            kind = effect.get("type")
            # Figma's blur radius is twice the Gaussian standard deviation, as in CSS.
            sigma = num((effect.get("radius") or 0) / 2 * scale)
            if kind == "DROP_SHADOW":
                color = effect.get("color") or {}
                offset = effect.get("offset") or {}
                dx, dy = offset.get("x", 0), offset.get("y", 0)
                odx, ody = m[0] * dx + m[1] * dy, m[3] * dx + m[4] * dy
                layers.append(
                    f'<feDropShadow dx="{num(odx)}" dy="{num(ody)}" stdDeviation="{sigma}" '
                    f'flood-color="{hex_color(color)}" flood-opacity="{num_precise(color.get("a", 1))}"/>'
                )
                if effect.get("spread"):
                    self.skipped["shadow spread"] += 1
            elif kind == "FOREGROUND_BLUR":
                layers.append(f'<feGaussianBlur stdDeviation="{sigma}"/>')
            else:
                self.skipped[f"{(kind or 'unknown').lower()} effect"] += 1
        if not layers:
            return None
        fid = self.uid("e")
        self.defs.append(
            f'<filter id="{fid}" x="-50%" y="-50%" width="200%" height="200%" color-interpolation-filters="sRGB">'
            + "".join(layers)
            + "</filter>"
        )
        return fid

    # --- instances ----------------------------------------------------------

    @staticmethod
    def key_of(node) -> str | None:
        """Override paths name a sublayer by its overrideKey when it has one, else by its guid."""
        return guid_key(node.get("overrideKey")) or guid_key(node.get("guid"))

    def apply_context(self, node, ctx, path):
        if not path:
            return node
        merged = node
        for table in (ctx.get("overrides", {}), ctx.get("derived", {})):
            fields = table.get(path)
            if fields:
                merged = {**merged, **fields}
        return merged

    def children_of(self, node, ctx, path):
        kind = node.get("type")
        if kind != "INSTANCE":
            return [
                (c, {**ctx, "child": True}, path + (self.key_of(c),) if path else ()) for c in self.graph.kids(node)
            ]
        master = self.graph.by_id.get(
            guid_key(node.get("overriddenSymbolID")) or guid_key((node.get("symbolData") or {}).get("symbolID"))
        )
        if master is None:
            self.skipped["instance whose component is not in the file"] += 1
            return []
        overrides = dict(ctx.get("overrides", {}))
        derived = dict(ctx.get("derived", {}))
        symbol = node.get("symbolData") or {}
        if symbol.get("uniformScaleFactor") not in (None, 1, 1.0):
            self.skipped["scaled instance drawn at component size"] += 1
        # An outer instance's overrides beat the nested instance's own.
        for entry in symbol.get("symbolOverrides") or []:
            rel = tuple(guid_key(g) for g in (entry.get("guidPath") or {}).get("guids") or [])
            fields = {k: v for k, v in entry.items() if k != "guidPath"}
            overrides.setdefault(path + rel, fields)
        for entry in node.get("derivedSymbolData") or []:
            rel = tuple(guid_key(g) for g in (entry.get("guidPath") or {}).get("guids") or [])
            fields = {k: v for k, v in entry.items() if k != "guidPath"}
            derived.setdefault(path + rel, fields)
        inner = {"overrides": overrides, "derived": derived, "child": True}
        return [(c, inner, path + (self.key_of(c),)) for c in self.graph.kids(master)]

#!/usr/bin/env node
import { fileURLToPath } from "node:url";

/** Parse a figma.com link into the file key and API-form node ID (`1:2`). */
export function parseFigmaUrl(input) {
  const url = new URL(input);
  if (!/(^|\.)figma\.com$/.test(url.hostname)) throw new Error(`Not a Figma link: ${input}`);
  const match =
    /^\/(design|file|proto|board|slides|make)\/([A-Za-z0-9]+)(?:\/[^/]*\/branch\/([A-Za-z0-9]+))?/.exec(
      url.pathname,
    );
  if (!match) throw new Error(`No file key in Figma link: ${input}`);
  const nodeId = url.searchParams.get("node-id");
  // A branch link's branch key addresses the branch's own file.
  return {
    fileKey: match[3] ?? match[2],
    nodeId: nodeId ? nodeId.replaceAll("-", ":") : null,
    kind: match[1],
  };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (!process.argv[2]) {
    console.error("Usage: figma-url.mjs <figma url>");
    process.exit(2);
  }
  console.log(JSON.stringify(parseFigmaUrl(process.argv[2])));
}

import { test } from "node:test";
import { strict as assert } from "node:assert";
import { parseFigmaUrl } from "./figma-url.mjs";

test("parses a design link with a node", () => {
  assert.deepEqual(parseFigmaUrl("https://www.figma.com/design/AbC123/Landing?node-id=12-34&t=x"), {
    fileKey: "AbC123",
    nodeId: "12:34",
    kind: "design",
  });
});

test("uses the branch key for a branch link", () => {
  assert.equal(
    parseFigmaUrl("https://www.figma.com/design/Main1/Name/branch/Br4nch/Name").fileKey,
    "Br4nch",
  );
});

test("accepts legacy file links without a node", () => {
  assert.deepEqual(parseFigmaUrl("https://figma.com/file/Old999/Name"), {
    fileKey: "Old999",
    nodeId: null,
    kind: "file",
  });
});

test("converts every hyphen in an instance sublayer id", () => {
  assert.equal(
    parseFigmaUrl("https://www.figma.com/design/AbC123/Name?node-id=I5-9%3B12-34").nodeId,
    "I5:9;12:34",
  );
});

test("rejects non-Figma links", () => {
  assert.throws(() => parseFigmaUrl("https://example.com/design/AbC123"), /Not a Figma link/);
  assert.throws(() => parseFigmaUrl("https://notfigma.com/design/AbC123"), /Not a Figma link/);
});
